"""Inspect the generated bytes independently of the page metadata.

This is a stream inventory, not a replacement text renderer. It follows shifts,
designations and control operands so PDI data cannot count as printable text.
"""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parent


def inventory(data):
    gs=['primary','pdi','supplementary','mosaic']
    gl=0; ss=None; pending=None; recording=False
    result=dict(primary=set(),supplementary=set(),mosaic=set(),drcs=set(),c0=set(),c1=set(),pdis=[],text=[],palette=[])
    def flush():
        nonlocal pending
        if pending is None: return
        op,values,offset=pending
        result['pdis'].append(dict(opcode=op,data=list(values),offset=offset,definition=recording))
        if op==0x22 and len(values)>=2:
            result['text'].append(dict(spacing=values[0]>>4&3,path=values[0]>>2&3,rotation=values[0]&3,motion=values[1]>>2&3,rows=values[1]&3))
        if op==0x3c: result['palette'].append(offset)
        pending=None
    i=0
    while i<len(data):
        off=i; b=data[i]; i+=1
        if b<32:
            result['c0'].add(b)
            if b not in (14,15,25,29): flush()
            if b==14: gl=1
            elif b==15: gl=0
            elif b==25: ss=2
            elif b==29: ss=3
            elif b==28: i+=2
            elif b==31:
                gs=['primary','pdi','supplementary','mosaic']; gl=0; ss=None
                if i+1<len(data) and 0x40<=data[i]<=0x7f and 0x40<=data[i+1]<=0x7f: i+=2
            elif b==27:
                c=data[i]; i+=1
                if 0x40<=c<=0x5f:
                    result['c1'].add(c)
                    if c in (0x40,0x41,0x42,0x43,0x44):
                        i+=1; recording=True
                    elif c==0x45: recording=False
                    elif c==0x46: i+=1
                elif c in (0x28,0x29,0x2a,0x2b,0x2d,0x2e,0x2f):
                    while data[i]<0x30: i+=1
                    final=data[i]; i+=1
                    target={0x28:0,0x29:1,0x2d:1,0x2a:2,0x2e:2,0x2b:3,0x2f:3}[c]
                    gs[target]={0x42:'primary',0x57:'pdi',0x7c:'supplementary',0x7d:'mosaic',0x7b:'drcs',0x7a:'macro'}[final]
                elif c in (0x6e,0x6f): gl=c-0x6c
                elif 0x20<=c<=0x2f:
                    while i<len(data) and 0x20<=data[i]<=0x2f: i+=1
                    i+=1
            continue
        charset=gs[ss if ss is not None else gl]; ss=None
        if charset=='pdi':
            if b<0x40:
                flush(); pending=(b,bytearray(),off)
            elif pending is not None: pending[1].append(b)
        else:
            flush()
            if not recording and charset in result:
                if b!=0x7f or charset in ('mosaic','drcs'): result[charset].add(b)
    flush()
    return result


def main():
    manifest=json.loads((ROOT/'out/manifest.json').read_text())
    records={m['number']:inventory((ROOT/'out'/m['file']).read_bytes()) for m in manifest}
    def union(key): return set().union(*(r[key] for r in records.values()))
    assert set(range(32,127))<=union('primary')
    assert {0x4a,0x4b,0x4c,0x4d,0x4f}<=records[111]['c1']
    assert {8,9,10,11,13,28,30,31}<=union('c0')
    assert {0x46,0x47,0x48,0x49,0x4e,0x57,0x58,0x59,0x5a}<=union('c1')
    assert {0x41,0x42,0x44,0x48,0x4b,0x23,0x25,0x22,0x2b,0x2c,0x2e,0x3b,0x3c,0x3d}<=union('supplementary')
    text=[t for r in records.values() for t in r['text']]
    for key in ('spacing','path','rotation','motion','rows'): assert {t[key] for t in text}=={0,1,2,3},key
    assert records[119]['drcs']=={0x21}
    assert {0x23,0x7f}<=records[119]['mosaic']
    blink_pages=[]
    for num,r in records.items():
        assert len(r['palette'])==16,(num,r['palette'])
        assert all(len(p['data'])==4 for p in r['pdis'] if p['opcode']==0x3c)
        selected=None; entries=[]
        for command in r['pdis']:
            if command['opcode']==0x3e and command['data']: selected=command['data'][0]>>2&15
            elif command['opcode']==0x3c: entries.append(selected)
        assert entries==list(range(16)),(num,entries)
        assert not any(p['opcode']==0x3d for p in r['pdis'])
        if 0x4e in r['c1'] or any(p['opcode']==0x3f for p in r['pdis']): blink_pages.append(num)
    assert blink_pages==[119]
    report=dict(printable_ascii_count=len(union('primary')),missing_printable_ascii=[],explicit_palette_entries_per_page=16,all_text_bitfields_cover=[0,1,2,3],blink_pages=blink_pages,wait_pages=[],pages={})
    for num,r in records.items():
        report['pages'][num]={k:(' '.join(f'{x:02X}' for x in sorted(v)) if isinstance(v,set) else v) for k,v in r.items()}
    (ROOT/'out/coverage-audit.json').write_text(json.dumps(report,indent=2)+'\n')
    print('Stream audit: all 95 printable ASCII characters; all four values of each TEXT bitfield; five C1 presets; sixteen explicit palette entries per page; only page 119 blinks; no WAIT.')


if __name__=='__main__': main()
